--
-- Table structure for table 'SYS_NOTIFICATION_CATEGORY_M'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE SYS_NOTIFICATION_CATEGORY_M';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE SYS_NOTIFICATION_CATEGORY_M (
    ID VARCHAR2(32) NOT NULL,
    PARENT_ID VARCHAR2(32) NULL,
    NAME VARCHAR2(50) NULL,
    TAG VARCHAR2(100) NULL,
    MENU_ID VARCHAR2(32) NULL,
    LIST_URL VARCHAR2(255) NULL,
    DETAIL_URL VARCHAR2(255) NULL,
    RESOURCE_CONTENT VARCHAR2(255) NULL,
    ROLE_FILTER NUMBER(2,0) NULL,
    SORT NUMBER(4,0) NULL,
    CONTENT VARCHAR2(255) NULL,
    "TYPE" NUMBER(2,0) NULL,
    STAR_TARGET VARCHAR2(10) NULL,
    NOTIFY_OBJECT_TYPE NUMBER(10) NULL,
    EMAIL_IND NUMBER(10) NULL
);

COMMENT ON COLUMN SYS_NOTIFICATION_CATEGORY_M.ROLE_FILTER IS '是否过滤角色';
COMMENT ON COLUMN SYS_NOTIFICATION_CATEGORY_M.CONTENT IS '消息模版内容';
COMMENT ON COLUMN SYS_NOTIFICATION_CATEGORY_M."TYPE" IS '1、通知。2、待处理';
COMMENT ON COLUMN SYS_NOTIFICATION_CATEGORY_M.NOTIFY_OBJECT_TYPE IS '提醒对象类型 0-所有角色;1-按角色发送; 2-按用户发送';
COMMENT ON COLUMN SYS_NOTIFICATION_CATEGORY_M.EMAIL_IND IS '是否发送Email';


