--
-- Table structure for table 'TENANT_PRE_CMS_LOAN_TYPE'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TENANT_PRE_CMS_LOAN_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE TENANT_PRE_CMS_LOAN_TYPE (
    ID VARCHAR2(32) NOT NULL,
    CODE VARCHAR2(4) NULL,
    NAME VARCHAR2(20) NULL,
    "TYPE" CHAR(1) NULL,
    STATUS NUMBER(2,0) NULL,
    IS_DEFAULT CHAR(1) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    CREATE_NAME VARCHAR2(50) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    UPDATE_NAME VARCHAR2(50) NULL,
    TENANT_ID VARCHAR2(32) NULL,
    IS_INIT CHAR(1) DEFAULT '1' NULL,
    CMS_LOAN_TYPE_MANAGER_ID VARCHAR2(32) NULL
);

COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.ID IS '主键';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.CODE IS '类型编号';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.NAME IS '类型名称';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE."TYPE" IS '类型';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.STATUS IS '状态';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.IS_DEFAULT IS '是否默认';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.TENANT_ID IS '租户ID';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.IS_INIT IS '是否初始化';
COMMENT ON COLUMN TENANT_PRE_CMS_LOAN_TYPE.CMS_LOAN_TYPE_MANAGER_ID IS '系统借款类型ID';


