--
-- Table structure for table 'TENANT_PRE_FBS_ITEM'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TENANT_PRE_FBS_ITEM';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE TENANT_PRE_FBS_ITEM (
    ID VARCHAR2(32) NOT NULL,
    ITEM_CODE VARCHAR2(40) NOT NULL,
    ITEM_NAME VARCHAR2(100) NULL,
    SUPER_ITEM_CODE VARCHAR2(40) NULL,
    LEVELS NUMBER(5,0) NULL,
    SIGN NUMBER(5,0) NULL,
    IS_INTERNAL VARCHAR2(1) NOT NULL,
    IS_CONTROL VARCHAR2(1) NULL,
    IS_RIGID VARCHAR2(1) NULL,
    IS_BEGIN_PERIOD VARCHAR2(1) NULL,
    IS_END_PERIOD VARCHAR2(1) NULL,
    VALID_SIGN VARCHAR2(1) NOT NULL,
    ITEM_RELATION CLOB NULL,
    OVER_PER_SPEND NUMBER(10,2) NULL,
    RMK VARCHAR2(200) NULL,
    IS_SYSTEM VARCHAR2(1) NULL,
    seq_code VARCHAR2(1000) NULL,
    SUPER_ITEM_CODES VARCHAR2(150) NULL,
    IS_WRITE CHAR(1) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    CASH_ITEM_CODE VARCHAR2(60) NULL,
    CASH_ITEM_NAME VARCHAR2(100) NULL,
    ALLOT_ITEM_CODE VARCHAR2(40) NULL,
    IS_WRITE_DETAIL VARCHAR2(1) DEFAULT '0' NULL,
    IS_INIT CHAR(1) DEFAULT '1' NULL
);

COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.ID IS '主建';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.ITEM_CODE IS '科目代码';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.ITEM_NAME IS '科目名称';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.SUPER_ITEM_CODE IS '父科目';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.LEVELS IS '科目层级';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.SIGN IS '资金流向1， 资金流入-1 ，资金流出';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_INTERNAL IS '是否冲抵科目  1-是 0-否';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_CONTROL IS '是否计划控制科目 1-是 0-否';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_RIGID IS '是否刚性科目 1-是 0-否';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_BEGIN_PERIOD IS '是否期初科目 1-是 0-否';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_END_PERIOD IS '是否期末科目 1-是 0-否';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.VALID_SIGN IS '有效标志 0 无效 1 有效';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.OVER_PER_SPEND IS '超计划比例';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.RMK IS '备注';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_SYSTEM IS '是否系统科目（系统科目不能删除）系统科目：100-期初资金，200-资金增加，300-可用资金，400-资金减少，500-资金不足或多余，600-新增筹资或还款，700-期末资金，800表外科目';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.SUPER_ITEM_CODES IS '存父的所有的编码,用逗号分隔';
COMMENT ON COLUMN TENANT_PRE_FBS_ITEM.IS_WRITE IS '是否允许填写计划 1-是 0-否';


