--
-- Table structure for table 'TENANT_PRE_FC_VOUCHER_TYPE'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TENANT_PRE_FC_VOUCHER_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE TENANT_PRE_FC_VOUCHER_TYPE (
    ID VARCHAR2(32) NOT NULL,
    VOUCHER_TYPE VARCHAR2(2) NOT NULL,
    VOUCHER_NAME VARCHAR2(20) NOT NULL,
    SYS_VOUCHER_CODE VARCHAR2(2) NULL,
    CASH_TRANS_SIGN VARCHAR2(1) NULL,
    SETTL_TYPE VARCHAR2(1) NULL,
    IS_ELECTRON_PAY VARCHAR2(1) NULL,
    IS_ACCOUNT VARCHAR2(1) NULL,
    IS_BUDGET VARCHAR2(1) NULL,
    RMK VARCHAR2(40) NULL,
    VALID_SIGN VARCHAR2(1) NULL,
    IS_SYSTEM VARCHAR2(1) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    SEND_MODE CHAR(1) DEFAULT '0' NULL,
    BIll_SECTION_CONTROL VARCHAR2(1) NULL,
    TENANT_ID VARCHAR2(32) NULL,
    IS_INIT CHAR(1) DEFAULT '1' NULL
);

COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.ID IS 'id';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.VOUCHER_TYPE IS '付款方式编码';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.VOUCHER_NAME IS '付款方式名称';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.SYS_VOUCHER_CODE IS '系统结算方式';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.CASH_TRANS_SIGN IS '现金转账标志';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.SETTL_TYPE IS '结算类型';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.IS_ELECTRON_PAY IS '是否走银企接口';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.IS_ACCOUNT IS '是否记账';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.IS_BUDGET IS ' 是否挂预算';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.RMK IS '备注';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.VALID_SIGN IS '有效标志';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.BIll_SECTION_CONTROL IS '开票区间控制标识 1-三个月 2-六个月';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.TENANT_ID IS '租户ID';
COMMENT ON COLUMN TENANT_PRE_FC_VOUCHER_TYPE.IS_INIT IS '是否初始化';


