--
-- Table structure for table 'TENANT_P_NOTIFICATION_CATEGORY'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE TENANT_P_NOTIFICATION_CATEGORY';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE TENANT_P_NOTIFICATION_CATEGORY (
    ID VARCHAR2(65) NOT NULL,
    PARENT_ID VARCHAR2(65) NULL,
    NAME VARCHAR2(50) NULL,
    TAG VARCHAR2(100) NULL,
    MENU_ID VARCHAR2(65) NULL,
    LIST_URL VARCHAR2(255) NULL,
    DETAIL_URL VARCHAR2(255) NULL,
    RESOURCE_CONTENT VARCHAR2(255) NULL,
    ROLE_FILTER NUMBER(2,0) NULL,
    SORT NUMBER(4,0) NULL,
    CONTENT VARCHAR2(2000) NULL,
    "TYPE" NUMBER(2,0) NULL,
    STAR_TARGET VARCHAR2(10) NULL,
    MENU_NAME VARCHAR2(100) NULL,
    WEIXIN_IND SMALLINT NULL,
    NOTIFY_OBJECT_TYPE NUMBER(10) NULL,
    IS_INIT CHAR(1) DEFAULT '1' NULL
);

COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY.ROLE_FILTER IS '是否过滤角色';
COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY.CONTENT IS '消息模版内容';
COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY."TYPE" IS '1、通知。2、待处理';
COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY.MENU_NAME IS '鑿滃崟鍚嶇О';
COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY.NOTIFY_OBJECT_TYPE IS '提醒对象类型 0-所有角色；1-按角色发送； 2-按用户发送';
COMMENT ON COLUMN TENANT_P_NOTIFICATION_CATEGORY.IS_INIT IS '是否初始化';


