CREATE TABLE SYS_CALENDAR_MANAGER (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    CALENDAR_NUM NUMBER(14,0) NOT NULL,
    WORK_DAY_SIGN NUMBER(6,0) NOT NULL,
    MONTH_END_SIGN NUMBER(6,0) NOT NULL,
    YEAR_END_SIGN NUMBER(6,0) NOT NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    COUNTRY_ID VARCHAR2(65) NULL,
    CUR_ID VARCHAR2(32) NULL,
    IS_INIT CHAR(1) DEFAULT '1' NULL
);

COMMENT ON TABLE SYS_CALENDAR_MANAGER IS '日历管理表';
COMMENT ON COLUMN SYS_CALENDAR_MANAGER.ID IS '主键ID';
COMMENT ON COLUMN SYS_CALENDAR_MANAGER.IS_INIT IS '是否初始化';


