    PATH CLOB NULL,
    DESCRIPTION VARCHAR2(225) NULL,
    CATEGORY VARCHAR2(30) NULL,
    STATUS NUMBER(2,0) NULL,
    GROUP_ID VARCHAR2(32) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL
);

