COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER."TYPE" IS '附件类型';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.SUFFIX IS '附件后缀';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.FILE_SIZE IS '附件大小';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.PATH IS '附件地址';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.DESCRIPTION IS '附件描述';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.CATEGORY IS '附件分类';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.STATUS IS '状态';
COMMENT ON COLUMN SYS_ATTACHMENT_MANAGER.GROUP_ID IS '组别id';


